#!/usr/bin/env node
//
// Regenerates Formula/inkentry.rb from a string-literal template.
//
// The formula is always written from scratch from the template below — there
// is no "first run vs. subsequent run" special-casing and no TODO_* placeholder
// matching. Given a version and the four release-asset sha256 digests, this
// script produces the exact file contents and writes them out.
//
// The output is written into a checkout of the inkentries/homebrew-inkentry
// tap repo by the update-homebrew-formula job in
// .github/workflows/release.yml, which then commits and pushes it.
//
// Usage:
//   node update-homebrew-formula.js \
//     --version 0.8.1 \
//     --sha-aarch64-darwin <hex> \
//     --sha-aarch64-linux <hex> \
//     --sha-x86_64-linux <hex> \
//     [--out Formula/inkentry.rb]
//
// Each --sha-* flag may also be supplied via the environment using the
// matching SHA_* variable name (e.g. SHA_AARCH64_DARWIN) — flags win if both
// are present. VERSION may also come from the VERSION env var.
//
// Only Node.js builtins are used (fs, path) — no extra npm dependencies.

"use strict";

const fs = require("fs");
const path = require("path");

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (!arg.startsWith("--")) continue;
    const key = arg.slice(2);
    const value = argv[i + 1];
    if (value === undefined || value.startsWith("--")) {
      throw new Error(`Missing value for --${key}`);
    }
    args[key] = value;
    i++;
  }
  return args;
}

function requireValue(name, ...sources) {
  for (const source of sources) {
    if (source !== undefined && source !== null && source !== "") {
      return source;
    }
  }
  throw new Error(
    `Missing required value: ${name} (pass it as a flag or environment variable)`
  );
}

function assertSha256(name, value) {
  if (!/^[0-9a-f]{64}$/i.test(value)) {
    throw new Error(
      `Invalid sha256 for ${name}: "${value}" (expected 64 hex characters)`
    );
  }
  return value.toLowerCase();
}

function buildFormula({ version, shaAarch64Darwin, shaAarch64Linux, shaX86_64Linux }) {
  return `class Inkentry < Formula
  desc "Code intelligence for AI agents — persistent memory, code graph, search"
  homepage "https://github.com/inkentries/inkentry"
  license "MIT"
  version "${version}"

  # Install:
  #   brew install inkentries/inkentry/inkentry
  #
  # This file is generated by update-homebrew-formula.js in
  # inkentries/inkentry, invoked from the update-homebrew-formula job in
  # .github/workflows/release.yml on every stable tag push, and pushed here
  # automatically. Do not hand-edit the version/sha256 values — they will be
  # overwritten on the next release.
  #
  # Note: x86_64-apple-darwin (Intel Mac) is no longer offered as a prebuilt
  # target — Apple deprecated the architecture and it has not shipped on new
  # hardware in years. Intel Mac users should build from source; see
  # docs/getting-started.md.

  on_macos do
    on_arm do
      url "https://github.com/inkentries/inkentry/releases/download/v#{version}/inkentry-v#{version}-aarch64-apple-darwin.tar.gz"
      sha256 "${shaAarch64Darwin}"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/inkentries/inkentry/releases/download/v#{version}/inkentry-v#{version}-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "${shaAarch64Linux}"
    end
    on_intel do
      url "https://github.com/inkentries/inkentry/releases/download/v#{version}/inkentry-v#{version}-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "${shaX86_64Linux}"
    end
  end

  def install
    bin.install "inkentry"
    bin.install "inkentry-server"
  end

  test do
    system "#{bin}/inkentry", "--version"
  end

  def caveats
    <<~EOS
      Run \`inkentry init\` in a project directory to get started.
      To start the local server: \`inkentry server start\`
    EOS
  end
end
`;
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const env = process.env;

  const rawVersion = requireValue("--version", args.version, env.VERSION);
  // Accept either "v0.8.1" or "0.8.1" — the formula's `version` field never
  // carries the leading "v" (the URL templates add it back via "v#{version}").
  const version = rawVersion.replace(/^v/, "");

  const shaAarch64Darwin = assertSha256(
    "aarch64-apple-darwin",
    requireValue(
      "--sha-aarch64-darwin",
      args["sha-aarch64-darwin"],
      env.SHA_AARCH64_DARWIN
    )
  );
  const shaAarch64Linux = assertSha256(
    "aarch64-unknown-linux-gnu",
    requireValue(
      "--sha-aarch64-linux",
      args["sha-aarch64-linux"],
      env.SHA_AARCH64_LINUX
    )
  );
  const shaX86_64Linux = assertSha256(
    "x86_64-unknown-linux-gnu",
    requireValue(
      "--sha-x86_64-linux",
      args["sha-x86_64-linux"],
      env.SHA_X86_64_LINUX
    )
  );

  const outPath = path.resolve(
    requireValue("--out", args.out, "Formula/inkentry.rb")
  );

  const formula = buildFormula({
    version,
    shaAarch64Darwin,
    shaAarch64Linux,
    shaX86_64Linux,
  });

  fs.writeFileSync(outPath, formula, "utf8");
  process.stdout.write(`Wrote ${outPath}\n`);
  process.stdout.write(formula);
}

main();
